  private var seed = 2463534242L

  private fun nextRandom(): Long {
    seed = seed xor ((seed shl 13) and 0xFFFFFFFFL)
    seed = seed xor (seed ushr 17)
    seed = seed xor ((seed shl 5) and 0xFFFFFFFFL)
    return seed
  }

  // Every entry draws from a stream of its own, so a new entry changes no other entry's inputs.
  private var inputRound = 0

  private fun reseed(entry: Long) {
    seed = (entry xor (inputRound * 2654435761L)) and 0xFFFFFFFFL
    if (seed == 0L) seed = 2463534242L
    nextRandom()
    nextRandom()
  }

  private fun nv(): Double {
    val r = nextRandom()
    return ((r % 200001) - 100000) / 10000.0 * SCALES[((r ushr 24) % 7).toInt()]
  }

  private fun ri(): Int = ((nextRandom() % 60001) - 30000).toInt()

  private fun rnz(): Int = ri().let { if (it == 0) 1 else it }

  private fun rs(): Int = (nextRandom() % 6).toInt()

  private fun rl(): Long = nextRandom()

  private fun rb(): Boolean = (nextRandom() and 1L) == 1L

  private fun rotation2D(x: Vector2, origin: Vector2): Transform2D =
    Transform2D(x, x.orthogonal(), origin)

  private val hashes = linkedMapOf<String, Long>()

  // The facade row records the Web-local methods' float components for the ulp comparison.
  private var recordValues = false
  private val values = linkedMapOf<String, MutableList<Double>>()

  private fun mixLong(name: String, value: Long) {
    for (bits in longArrayOf(value and 0xFFFFFFFFL, (value ushr 32) and 0xFFFFFFFFL)) {
      hashes[name] = ((hashes[name] ?: 2166136261L) xor bits) * 16777619L and 0xFFFFFFFFL
    }
  }

  private fun mix(key: String, value: Any?) {
    val name = key.replace(' ', '_')
    when (value) {
      null -> mixLong(name, -1L)
      is Double -> {
        if (recordValues) values.getOrPut(name) { mutableListOf() }.add(value)
        mixLong(name, if (value.isNaN()) 0x7FF8000000000000L else value.toRawBits())
      }
      is Long -> mixLong(name, value)
      is Int -> mixLong(name, value.toLong())
      is Boolean -> mixLong(name, if (value) 1L else 0L)
      is Float -> mix(key, value.toDouble())
      is ByteArray -> value.forEach { mixLong(name, it.toLong() and 0xFFL) }
      is String -> value.forEach { mixLong(name, it.code.toLong()) }
      is RID -> mixLong(name, value.value)
      is Vector2 -> listOf(value.x, value.y).forEach { mix(key, it) }
      is Vector3 -> listOf(value.x, value.y, value.z).forEach { mix(key, it) }
      is Vector4 -> listOf(value.x, value.y, value.z, value.w).forEach { mix(key, it) }
      is Quaternion -> listOf(value.x, value.y, value.z, value.w).forEach { mix(key, it) }
      is Color -> listOf(value.r, value.g, value.b, value.a).forEach { mix(key, it) }
      is Vector2i -> listOf(value.x, value.y).forEach { mix(key, it) }
      is Vector3i -> listOf(value.x, value.y, value.z).forEach { mix(key, it) }
      is Vector4i -> listOf(value.x, value.y, value.z, value.w).forEach { mix(key, it) }
      is Rect2 -> listOf(value.position, value.size).forEach { mix(key, it) }
      is Rect2i -> listOf(value.position, value.size).forEach { mix(key, it) }
      is AABB -> listOf(value.position, value.size).forEach { mix(key, it) }
      is Plane -> listOf(value.normal, value.d).forEach { mix(key, it) }
      is Basis -> listOf(value.x, value.y, value.z).forEach { mix(key, it) }
      is Transform2D -> listOf(value.x, value.y, value.origin).forEach { mix(key, it) }
      is Transform3D -> listOf(value.basis, value.origin).forEach { mix(key, it) }
      is Projection -> listOf(value.x, value.y, value.z, value.w).forEach { mix(key, it) }
      is List<*> -> value.forEach { mix(key, it) }
      else -> error("no parity mix for ${value::class}")
    }
  }

